import type { EngineInterface, On, PluginOptions, Timer } from 'claude-code'

import Band from './band'
import Biome, { type BiomeId } from './biome'
import Messages, { type Language } from './messages'
import Names from './names'
import Pet from './pet'
import Rng from './rng'
import Scene, { type Zoom } from './scene'
import Species, { type BreedId } from './species'
import View from './view'
import World from './world'

type Host = {
  now: () => Promise<number>
  every: (ms: number, fn: () => void) => Timer
  blit: (requestId: string, key: string, cells: string, cols: number, rows: number) => Promise<{ deny?: string }>
  invalidate: () => void
  store: (key: string, value: unknown) => Promise<void>
}

type Mount = { requestId: string; cols: number; rows: number; lastCells: string; lastAt: number }

// userConfig 의 language 가 auto 면 settings 의 language, LC_ALL, LANG 순으로 본다. $ 는 훅 안에만 있어 session.start 에서 부른다
async function languageIn($: Pick<EngineInterface, 'settings' | 'env'>, option: unknown): Promise<Language> {
  if (option === 'en' || option === 'ko') return option
  const valueOf = async (read: () => Promise<unknown>) => {
    try {
      return await read()
    } catch {
      return undefined
    }
  }
  return Messages.languageOf(option, [
    await valueOf(async () => (await $.settings.read()).language),
    await valueOf(() => $.env.get('LC_ALL')),
    await valueOf(() => $.env.get('LANG')),
  ])
}

// 세션 신호로 강아지를 움직이는 일은 부가 기능이다. 여기서 난 오류가 세션의 스트림·도구 호출을 막지 않게 삼킨다
function safely(fn: () => void): void {
  try { fn() } catch { /* 강아지 쪽 오류는 무시한다 */ }
}

// 저장한 맵 세트 값을 읽는다. 모르는 모양·버전·세트면 기본 세트
// 저장한 품종 값을 읽는다. 모르는 모양·버전·품종이면 기본 품종
function petChoiceOf(value: unknown): BreedId | 'auto' {
  if (typeof value !== 'object' || value === null) return Species.DEFAULT_BREED
  const v = value as { v?: unknown; list?: unknown }
  if (v.v !== Names.STORE_PETS_VERSION) return Species.DEFAULT_BREED
  if (v.list === 'auto') return 'auto'
  return Array.isArray(v.list) && Species.isBreedId(v.list[0]) ? v.list[0] : Species.DEFAULT_BREED
}

// 저장한 잠들지 않기 값을 읽는다. 모르는 모양·버전이면 꺼진 것으로 본다
function idleOf(value: unknown): boolean {
  if (typeof value !== 'object' || value === null) return false
  const v = value as { v?: unknown; on?: unknown }
  return v.v === Names.STORE_IDLE_VERSION && v.on === true
}

// Claude Code 테마가 밝은 계열이면 띠를 밝은 터미널용 색으로 그린다
function isLightTheme(value: unknown): boolean {
  return typeof value === 'string' && value.startsWith('light')
}

function worldChoiceOf(value: unknown): BiomeId | 'auto' {
  if (typeof value !== 'object' || value === null) return Biome.DEFAULT
  const v = value as { v?: unknown; set?: unknown }
  if (v.v !== Names.STORE_WORLD_VERSION) return Biome.DEFAULT
  return v.set === 'auto' || Biome.isId(v.set) ? v.set : Biome.DEFAULT
}

// 엔진이 기록한 이 플러그인의 열린 패널. 모듈을 다시 불러와도(언어 변경 등) 패널은 떠 있고 이 기록에 남는다
async function isPaneUp($: Pick<EngineInterface, 'ui'>, id: string): Promise<boolean> {
  try {
    return (await $.ui.panes()).some(pane => pane.id === id)
  } catch {
    return false
  }
}

export function register(on: On, options: PluginOptions) {
  let messages = Messages.messagesOf(Messages.languageOf(options.language))
  let host: Host | undefined
  let isOpen = false
  // 프롬프트 위 띠는 쓰지 않는 기능으로 둔다: 켜는 명령이 없고 예전 저장값(band 키)도 읽지 않아 늘 꺼져 있다
  let isBandOn = false
  let zoom: Zoom = Scene.DEFAULT_ZOOM
  let scene = Scene.create(0x5eed, 0)
  let band = Band.create(0x5eed, 0)
  let timer: Timer | undefined
  let timerMs = 0
  let pane: Mount | undefined
  let strip: Mount | undefined
  let isWorking = false
  let lastAt: number | undefined
  // 고른 맵 세트('auto' 면 세션 시드로 고른다)와 세션 시드
  let worldChoice: BiomeId | 'auto' = Biome.DEFAULT
  let petChoice: BreedId | 'auto' = Species.DEFAULT_BREED
  let isIdle = false
  let isLight = false
  let sessionSeed = 0x5eed
  // 마지막으로 저장한 편집 목록(JSON)과 저장을 마지막으로 살핀 시각. 목록이 같으면 다시 쓰지 않는다.
  // 지금 키에 모르는 버전·모양의 값이 있으면 이 세트·세션 동안 그 키에 쓰지 않는다(다른 버전의 저장값을 덮지 않는다)
  let editsSaved = ''
  let editsAt = 0
  let editsLocked = false

  function biomeOf(choice: BiomeId | 'auto'): BiomeId {
    return choice === 'auto' ? Biome.autoOf(sessionSeed) : choice
  }

  function breedOf(choice: BreedId | 'auto'): BreedId {
    return choice === 'auto' ? Species.autoBreed(sessionSeed) : choice
  }

  // 띠 강아지를 지금 품종과 터미널 밝기에 맞춘다
  function lookBand(): void {
    const breed = Species.breedOf(scene.breed)
    Band.setLook(band, Species.lookOf(breed.id), isLight ? breed.band.light : breed.band.dark)
    if (strip) strip.lastCells = ''
  }

  function editsKey(): string {
    return Names.STORE_EDITS_KEY(scene.biome, sessionSeed)
  }

  // 지금 세트·시드의 편집(옮긴 나뭇가지, 구덩이 흔적)을 읽는다. 모르는 버전·모양이면 빈 표로 두고 저장값은 지우지 않는다
  async function loadEdits(get: (key: string) => Promise<unknown>, now: number): Promise<void> {
    editsSaved = ''
    editsLocked = false
    try {
      const value = await get(editsKey())
      const edits = World.editsFromSave(value)
      if (!edits) {
        editsLocked = value !== undefined
        return
      }
      scene.world.edits = edits
      World.expireEdits(scene.world, now)
      editsSaved = JSON.stringify(World.editsToSave(scene.world, now).list)
    } catch { /* 못 읽으면 빈 표 */ }
  }

  // 편집이 바뀌었으면 저장한다
  async function saveEdits(h: Host, now: number): Promise<void> {
    if (editsLocked) return
    const value = World.editsToSave(scene.world, now)
    const text = JSON.stringify(value.list)
    if (text === editsSaved) return
    editsSaved = text
    await h.store(editsKey(), value)
  }

  // 편집 키는 지금 것 말고 가장 최근 것 EDITS_KEYS - 1 개까지만 남긴다(저장값의 at 이 오래된 것부터 지운다).
  // 모르는 버전·모양의 값은 세지도 지우지도 않는다
  async function pruneEdits(store: { keys: () => Promise<string[]>; get: (key: string) => Promise<unknown>; delete: (key: string) => Promise<void> }): Promise<void> {
    const mine = editsKey()
    const others = (await store.keys()).filter(k => k.startsWith(Names.STORE_EDITS_PREFIX) && k !== mine)
    if (others.length < Names.EDITS_KEYS) return
    const dated: Array<[string, number]> = []
    for (const k of others) {
      const v = await store.get(k)
      if (!World.editsFromSave(v)) continue
      const at = (v as { at?: unknown }).at
      dated.push([k, typeof at === 'number' ? at : 0])
    }
    dated.sort((a, b) => b[1] - a[1])
    for (const [k] of dated.slice(Names.EDITS_KEYS - 1)) await store.delete(k)
  }

  // 패널이 열려 있으면 강아지가 반응하고, 닫혀 있으면 신호 시각만 적는다(시뮬레이션도 멈춰 있다)
  function signal(now: number, react: () => void): void {
    safely(() => {
      if (isOpen) react()
      else scene.pet.lastSignalAt = now
    })
  }

  async function paint(h: Host, m: Mount, key: string, cells: string, now: number): Promise<void> {
    m.lastAt = now
    if (cells === m.lastCells) return
    m.lastCells = cells
    const result = await h.blit(m.requestId, key, cells, m.cols, m.rows)
    // 크기가 바뀌었거나 아직 붙지 않았다: 다시 그려 달라고 한다
    if (result.deny !== undefined) { m.lastCells = ''; h.invalidate() }
  }

  async function onFrame() {
    const h = host
    if (!h) return
    const now = await h.now()
    const dt = lastAt === undefined ? 0 : now - lastAt
    lastAt = now
    const p = pane
    if (isOpen && p) {
      Scene.step(scene, dt, now)
      Scene.prefetch(scene, p.cols, p.rows, zoom)
      if (now - p.lastAt >= Scene.renderEveryMs(scene) - 1) await paint(h, p, Names.RASTER_KEY, Scene.compose(scene, p.cols, p.rows, zoom), now)
      if (now - editsAt >= Names.EDITS_SAVE_MS) {
        editsAt = now
        try { await saveEdits(h, now) } catch { /* 다음에 다시 */ }
      }
    }
    const s = strip
    if (isBandOn && s) {
      Band.step(band, dt, now, isWorking)
      if (now - s.lastAt >= Band.renderEveryMs(band) - 1) await paint(h, s, Names.BAND_KEY, Band.compose(band, s.cols), now)
    }
  }

  // 타이머는 하나만 둔다. 패널이 열려 있으면 33 ms, 띠만 있으면 66 ms, 둘 다 없으면 멈춘다
  function syncTimer() {
    const want = isOpen && pane ? Names.FRAME_MS : isBandOn && strip ? Names.BAND_ONLY_FRAME_MS : 0
    if (want === timerMs) return
    timer?.cancel()
    timer = undefined
    timerMs = want
    lastAt = undefined
    if (want > 0 && host) timer = host.every(want, () => { void onFrame() })
  }

  on('session.start', async ($, e, next) => {
    host = {
      now: () => $.clock.now(),
      every: (ms, fn) => $.clock.every(ms, fn),
      blit: (requestId, key, cells, columns, rows) => $.ui.blit({ requestId, key, cells, columns, rows }),
      invalidate: () => $.ui.invalidate('ui.render'),
      store: (key, value) => $.store.set(key, value),
    }
    const now = await $.clock.now()
    let seed = (now | 0) ^ 0x5eed
    try { seed = Rng.hashOf(await $.session.id()) } catch { /* 시각으로 만든 시드 그대로 */ }
    sessionSeed = seed
    try {
      zoom = Scene.zoomOf(await $.store.get(Names.STORE_SCALE))
      worldChoice = worldChoiceOf(await $.store.get(Names.STORE_WORLD))
      petChoice = petChoiceOf(await $.store.get(Names.STORE_PETS))
      isIdle = idleOf(await $.store.get(Names.STORE_IDLE))
    } catch { /* 저장한 값이 없으면 기본값 */ }
    try { isLight = isLightTheme((await $.config.list()).find(row => row.key === 'theme')?.value) } catch { /* 모르면 어두운 터미널로 본다 */ }
    scene = Scene.create(seed, now, biomeOf(worldChoice), breedOf(petChoice))
    scene.pet.keepAwake = isIdle
    editsAt = now
    await loadEdits(key => $.store.get(key), now)
    try { await pruneEdits({ keys: () => $.store.keys(), get: key => $.store.get(key), delete: key => $.store.delete(key) }) } catch { /* 지우지 못하면 다음 세션에 */ }
    band = Band.create(seed, now)
    lookBand()
    messages = Messages.messagesOf(await languageIn($, options.language))
    await $.command.register({ name: Names.COMMAND_NAME, description: messages.commandDescription, argumentHint: messages.argumentHint })
    // 다시 불러온 모듈은 패널을 닫힌 것으로 안다. 패널이 떠 있으면 열린 상태로 되돌리고 다시 그려 프레임을 잇는다
    if (await isPaneUp($, Names.PANE_ID)) {
      isOpen = true
      scene.pet.lastSignalAt = now
      $.ui.invalidate('ui.render')
    }
    return next(e)
  })

  on('command.run', { command: Names.COMMAND_NAME }, async ($, e) => {
    const [arg = '', sub = '', ...rest] = e.args.trim().toLowerCase().split(/\s+/)
    // zoom 은 맵 보기 → 원거리 → 1 배 → 2 배 를 돌고, zoom in · out 은 한 단계씩 가다 끝에서 멈추고, zoom <wide|far|1|2> 는 그 단계로 바로 간다
    const named = arg === 'zoom' ? Scene.zoomNamed(sub) : undefined
    if (arg === 'zoom' && (sub === '' || sub === 'in' || sub === 'out' || named !== undefined) && rest.length === 0) {
      const next = named ?? (sub === '' ? Scene.zoomNext(zoom) : Scene.zoomBy(zoom, sub === 'in' ? 1 : -1))
      if (next === zoom) return { text: named !== undefined ? messages.zoomSame(zoom) : messages.zoomLimit(zoom) }
      zoom = next
      await host?.store(Names.STORE_SCALE, zoom)
      if (pane) {
        Scene.ensureVisible(scene, pane.cols, pane.rows, zoom)
        pane.lastCells = ''
      }
      $.ui.invalidate('ui.render')
      return { text: messages.zoomChanged(zoom) }
    }
    // world 는 지금 세트와 목록을 보이고, world <세트|auto> 는 세트를 바꿔 저장한다. 모르는 세트면 아무것도 바꾸지 않는다
    if (arg === 'world' && rest.length === 0) {
      const choices = messages.worldChoices(Biome.BIOMES.map(b => b.id))
      if (sub === '') return { text: messages.worldNow(messages.setLabels[scene.biome], worldChoice === 'auto', choices) }
      const picked = sub === 'auto' ? 'auto' : Biome.find(sub)?.id
      if (picked === undefined) return { text: messages.worldUnknown(sub, choices) }
      worldChoice = picked
      const now = await $.clock.now()
      if (host) {
        try { await saveEdits(host, now) } catch { /* 옛 세트 편집을 못 쓰면 버린다 */ }
      }
      Scene.setBiome(scene, biomeOf(picked), now)
      await loadEdits(key => $.store.get(key), now)
      await host?.store(Names.STORE_WORLD, { v: Names.STORE_WORLD_VERSION, set: picked })
      if (pane) {
        Scene.ensureVisible(scene, pane.cols, pane.rows, zoom)
        pane.lastCells = ''
      }
      $.ui.invalidate('ui.render')
      return { text: messages.worldChanged(messages.setLabels[scene.biome], picked === 'auto') }
    }
    // pet 은 지금 품종과 목록을 보이고, pet <품종…|auto> 는 품종을 바꿔 저장한다. 지금은 한 마리라 첫 번째만 쓴다
    if (arg === 'pet') {
      const choices = messages.petChoices(Species.BREEDS.map(b => b.id))
      if (sub === '') return { text: messages.petNow(messages.breedLabels[scene.breed], petChoice === 'auto', choices) }
      const picked = sub === 'auto' ? 'auto' : Species.findBreed(sub)?.id
      if (picked === undefined) return { text: messages.petUnknown(sub, choices) }
      petChoice = picked
      Scene.setBreed(scene, breedOf(picked))
      lookBand()
      await host?.store(Names.STORE_PETS, { v: Names.STORE_PETS_VERSION, list: picked === 'auto' ? 'auto' : [picked] })
      if (pane) pane.lastCells = ''
      $.ui.invalidate('ui.render')
      return { text: messages.petChanged(messages.breedLabels[scene.breed], picked === 'auto', rest.length) }
    }
    // idle 은 지금 상태를 보이고, idle on · off 는 잠들지 않기를 켜고 꺼 저장한다
    if (arg === 'idle' && rest.length === 0) {
      if (sub === '') return { text: messages.idleNow(isIdle, Names.SLEEP_AFTER_MS / 60_000, Names.SLEEP_MS / 60_000) }
      if (sub !== 'on' && sub !== 'off') return { text: messages.idleUsage }
      isIdle = sub === 'on'
      scene.pet.keepAwake = isIdle
      await host?.store(Names.STORE_IDLE, { v: Names.STORE_IDLE_VERSION, on: isIdle })
      return { text: messages.idleChanged(isIdle) }
    }
    // do <행동> 은 패널이 열려 있을 때 그 행동을 지금 시킨다. 못 하면 이유를 답하고 아무것도 바꾸지 않는다. id 나 별칭으로 받는다
    if (arg === 'do' && rest.length === 0) {
      const choices = messages.doChoices(Pet.ORDERS.map(o => o.id))
      if (sub === '') return { text: messages.doUsage(choices) }
      const name = Pet.findOrder(sub)
      if (name === undefined) return { text: messages.doUnknown(sub, choices) }
      if (!isOpen) return { text: messages.doClosed }
      const refusal = Pet.order(scene.pet, scene.world, await $.clock.now(), name)
      if (refusal) return { text: messages.doRefused[refusal] }
      return { text: messages.doDone(messages.orderLabels[name]) }
    }
    if (arg !== '') return { text: messages.usage }
    if (isOpen) {
      await $.ui.close({ id: Names.PANE_ID })
      isOpen = false
      pane = undefined
      syncTimer()
      return { text: messages.panelHidden }
    }
    const docked = e.presentation?.isFullscreen === true
    await $.ui.open(docked
      ? { id: Names.PANE_ID, title: Names.PANE_TITLE, holdToasts: true, columns: Names.COLS }
      : { id: Names.PANE_ID, title: Names.PANE_TITLE, holdToasts: true, rows: Names.INLINE_ROWS })
    isOpen = true
    // 패널을 여는 것도 신호로 친다. 오래 닫아 두었다 열었을 때 강아지가 보자마자 잠자리로 가지 않는다
    scene.pet.lastSignalAt = await $.clock.now()
    return { text: messages.panelShown }
  })

  // 테마를 바꾸면 띠 색 벌도 바꾼다(거절된 변경은 넘긴다)
  on('config.set', { key: 'theme' }, async ($, e, next) => {
    const result = await next(e)
    if (result.deny === undefined) {
      safely(() => {
        isLight = isLightTheme(result.value)
        lookBand()
      })
    }
    return result
  })

  on('ui.close', { id: Names.PANE_ID }, async ($, e, next) => {
    const result = await next(e)
    if (result.deny === undefined) { isOpen = false; pane = undefined; syncTimer() }
    return result
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== Names.PANE_ID) return next(e)
    const cols = e.props.bodyColumns
    const rows = e.props.scroll.bodyRows
    // Raster 는 터미널 표면에만 있다. 요소 표에 이름이 있는지로는 가를 수 없어 표면으로 가른다
    if (e.surface !== 'terminal') {
      pane = undefined
      syncTimer()
      return View.noticeView($.ui.resolve(e), [messages.notTerminal])
    }
    const kit = $.ui.resolve(e)
    if (cols < Names.MIN_COLS || rows < Names.MIN_ROWS) {
      pane = undefined
      syncTimer()
      return View.noticeView(kit, messages.tooSmall(Names.MIN_COLS, Names.MIN_ROWS, cols, rows))
    }
    const now = await $.clock.now()
    Scene.ensureVisible(scene, cols, rows, zoom)
    const cells = Scene.compose(scene, cols, rows, zoom)
    pane = { requestId: e.requestId, cols, rows, lastCells: cells, lastAt: now }
    if (isOpen) syncTimer()
    return View.rasterView(kit.Raster, Names.RASTER_KEY, cols, rows, cells)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    isWorking = e.props.isWorking
    // 설문이 띠를 쓰는 동안이나 띠가 3 행이 안 될 때는 비켜 준다
    if (!isBandOn || e.props.hasSurvey || e.props.maxRows < Names.BAND_ROWS) {
      strip = undefined
      syncTimer()
      return next(e)
    }
    if (e.surface !== 'terminal') return next(e)
    const kit = $.ui.resolve(e)
    const cols = Math.max(1, Math.min(512, e.props.bodyColumns))
    const now = await $.clock.now()
    const cells = Band.compose(band, cols)
    strip = { requestId: e.requestId, cols, rows: Names.BAND_ROWS, lastCells: cells, lastAt: now }
    syncTimer()
    return View.rasterView(kit.Raster, Names.BAND_KEY, cols, Names.BAND_ROWS, cells)
  })

  // 세션이 끝날 때 바뀐 편집을 저장한다
  on('session.end', async ($, e, next) => {
    try {
      if (host) await saveEdits(host, await $.clock.now())
    } catch { /* 못 쓰면 버린다 */ }
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    try {
      const now = await $.clock.now()
      isWorking = true
      signal(now, () => Scene.onTurnStart(scene, now, e.text))
      safely(() => Band.onTurnStart(band, now))
    } catch { /* 강아지 쪽 오류는 무시한다 */ }
    return next(e)
  })

  // 글이 흐르는 동안은 바쁜 것으로 본다(걷기·킁킁 비중이 오른다). 조각마다 시계를 읽지 않고 응답 시작과 조각 16 개마다 적는다
  async function markBusy(now: () => Promise<number>): Promise<void> {
    try {
      const t = await now()
      safely(() => { Pet.onStream(scene.pet, t); band.lastSignalAt = t })
    } catch { /* 시계를 못 읽으면 이번에는 건너뛴다 */ }
  }

  // 메인 루프 생각 조각은 첫 조각과 16 개마다 시각을 읽어 넘긴다. 글·도구 조각이 오면 생각이 끝난 것이다
  async function markThinking(now: () => Promise<number>): Promise<void> {
    try {
      const t = await now()
      signal(t, () => Pet.onThinkPiece(scene.pet, scene.world, t))
    } catch { /* 시계를 못 읽으면 이번에는 건너뛴다 */ }
  }

  on('turn.step', async function* ($, e, next) {
    const clock = () => $.clock.now()
    const isMain = e.agentId === undefined
    await markBusy(clock)
    const stream = next(e)
    let pieces = 0
    let thoughts = 0
    for await (const chunk of stream) {
      if ((chunk.kind === 'text' || chunk.kind === 'thinking' || chunk.kind === 'input') && ++pieces % 16 === 0) await markBusy(clock)
      if (isMain && chunk.kind === 'thinking' && thoughts++ % 16 === 0) await markThinking(clock)
      if (isMain && (chunk.kind === 'text' || chunk.kind === 'tool') && thoughts > 0) {
        thoughts = 0
        safely(() => Pet.onThinkEnd(scene.pet))
      }
      yield chunk
    }
    return await stream.result
  })

  // 메인 턴 끝에는 끝난 이유대로 반응하고, 서브에이전트의 턴 끝에는 잠깐 사람 쪽만 본다
  on('turn.complete', async ($, e, next) => {
    try {
      const now = await $.clock.now()
      if (e.agentId === undefined) {
        isWorking = false
        signal(now, () => Scene.onTurnEnd(scene, now, e.reason, e.durationMs))
        safely(() => Band.onTurnEnd(band, now))
      } else {
        signal(now, () => Pet.onSubagentEnd(scene.pet, scene.world, now))
      }
    } catch { /* 강아지 쪽 오류는 무시한다 */ }
    return next(e)
  })

  // 타이핑·턴 도중 입력은 키 입력 경로라 시계를 기다리지 않고 마지막 프레임 시각을 쓴다. 패널이 닫혀 있으면 아무것도 하지 않는다
  on('prompt.edit', async ($, e, next) => {
    const t = lastAt
    if (isOpen && t !== undefined) safely(() => Pet.onTyping(scene.pet, scene.world, t))
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    const t = lastAt
    if (isOpen && t !== undefined && e.turnId !== undefined && e.origin.kind === 'composer') safely(() => Pet.onPromptQueued(scene.pet, scene.world, t))
    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    try {
      const now = await $.clock.now()
      signal(now, () => Pet.onSubagentStart(scene.pet, scene.world, now))
    } catch { /* 강아지 쪽 오류는 무시한다 */ }
    return next(e)
  })

  // 사람이 부른 압축과 자동 압축만. 미리 계산해 두는 압축과 서브에이전트의 압축은 넘긴다
  on('session.compact', async ($, e, next) => {
    if (e.agentId === undefined && (e.trigger === 'manual' || e.trigger === 'auto')) {
      try {
        const now = await $.clock.now()
        signal(now, () => Pet.onCompact(scene.pet, scene.world, now))
      } catch { /* 강아지 쪽 오류는 무시한다 */ }
    }
    return next(e)
  })

  // 메인 루프 도구는 이름에 따라 반응하고 오류·거부에도 반응한다. 서브에이전트 도구는 얼굴만 돌린다
  on('tool.call', async ($, e, next) => {
    const isMain = e.agentId === undefined
    let started = false
    try {
      const now = await $.clock.now()
      safely(() => Pet.onToolStart(scene.pet, now, isMain))
      signal(now, () => isMain ? Scene.onTool(scene, now, e.tool) : Pet.onSubTool(scene.pet, now))
      safely(() => { Band.onToolStart(band, now); Band.onTool(band, now) })
      started = true
    } catch { /* 강아지 쪽 오류는 무시한다 */ }
    try {
      const result = await next(e)
      const fail = result.deny !== undefined ? 'deny' : result.isError === true ? 'error' : undefined
      if (isMain && fail) {
        try {
          const now = await $.clock.now()
          signal(now, () => Pet.onToolFail(scene.pet, scene.world, now, fail))
        } catch { /* 강아지 쪽 오류는 무시한다 */ }
      }
      return result
    } finally {
      // 도구가 도는 동안은 프레임마다 마지막 신호 시각이 갱신되므로 끝날 때는 세기만 줄인다
      if (started) {
        safely(() => {
          Pet.onToolEnd(scene.pet, scene.pet.lastSignalAt, isMain)
          Band.onToolEnd(band, band.lastSignalAt)
        })
      }
    }
  })
}

files.hooks/band/index.ts:
// 프롬프트 위 띠(AbovePrompt): 3 행 = 세로 6 픽셀짜리 옆모습 강아지가 가로로 걷고, 앉고, 킁킁대고, 잔다(순수 모듈).
// 패널의 강아지와 상태를 나누지 않는다. 세션 신호는 같은 것을 받는다.

import Names from '../names'
import Pixel, { Palette, type Buffer, type Grid } from '../pixel'
import Rng from '../rng'
import Species, { type BandColors, type BandFrame, type BandRole, type SpeciesDef } from '../species'

type Mode = 'idle' | 'walk' | 'run' | 'sit' | 'sniff' | 'sleep'

export type Band = {
  species: SpeciesDef
  // 번호마다의 RGB(품종의 띠 색 한 벌로 만든다)
  rgb: readonly number[]
  x: number
  // 1 = 오른쪽, -1 = 왼쪽
  dir: 1 | -1
  mode: Mode
  targetX: number
  // 지금 모드가 끝나는 시각까지 남은 시간(ms). 걷기·뛰기는 목적지에 닿으면 끝난다
  left: number
  // 걸은 거리(px). 발 모양을 거리로 바꾼다
  walked: number
  clock: number
  zAt: number
  rng: Rng.Rng
  lastSignalAt: number
  toolsRunning: number
  lastSniffAt: number
  width: number
  buf?: Buffer
  grid?: Grid
}

const H = Names.BAND_ROWS * 2
const FLOOR_Y = H - 1
const SNIFF_GAP_MS = 1500

// 띠는 패널 세트·품종 색 표를 빌리지 않고 자기 번호 표와 색 표로 접는다
export const FLOOR = 1
export const BODY = 2
export const UNDER = 3
export const LINE = 4
export const EYE = 5
export const EAR = 6
export const EAR_DARK = 7
export const COLLAR = 8
export const Z = 9
// 바닥 점선과 z 는 품종과 상관없는 회색이다
const FLOOR_RGB = 0x8f8b8d
const Z_RGB = 0xa29ea0

// 품종 띠 색 한 벌로 번호 표를 만든다. 패널 강아지와 같은 개로 보이도록 귀·꼬리·목줄 색도 품종이 정한다
export function rgbOf(c: BandColors): readonly number[] {
  return [Palette.DEFAULT_COLOR, FLOOR_RGB, c.body, c.under, c.line, c.eye, c.ear, c.earDark, c.collar, Z_RGB]
}

// 기본(흰 강아지, 어두운 터미널용)
export const RGB: readonly number[] = rgbOf(Species.DOG.breeds[0]!.band.dark)
const INDEX: Readonly<Record<BandRole, number>> = { body: BODY, under: UNDER, line: LINE, eye: EYE, ear: EAR, earDark: EAR_DARK, collar: COLLAR }

// 프레임(종 정의의 band.frames)은 오른쪽 보기, 아래 줄이 바닥 바로 위(y = 4). 가로 가운데가 x
export function create(seed: number, now: number, species: SpeciesDef = Species.DOG, colors: BandColors = Species.DOG.breeds[0]!.band.dark): Band {
  const rng = Rng.create(seed ^ 0xba5d)
  return { species, rgb: rgbOf(colors), x: 20, dir: 1, mode: 'idle', targetX: 20, left: 1500, walked: 0, clock: 0, zAt: 0, rng, lastSignalAt: now, toolsRunning: 0, lastSniffAt: -Infinity, width: 80 }
}

// 품종이나 터미널 밝기가 바뀌면 모습과 색만 바꾼다(움직임 상태는 그대로)
export function setLook(band: Band, species: SpeciesDef, colors: BandColors): void {
  band.species = species
  band.rgb = rgbOf(colors)
}

function go(band: Band, mode: 'walk' | 'run', minFrac: number): void {
  const lo = 6
  const hi = Math.max(lo + 1, band.width - 7)
  let x = Rng.range(band.rng, lo, hi)
  for (let i = 0; i < 6 && Math.abs(x - band.x) < band.width * minFrac; i++) x = Rng.range(band.rng, lo, hi)
  band.targetX = x
  band.dir = x >= band.x ? 1 : -1
  band.mode = mode
}

function next(band: Band, isWorking: boolean): void {
  const w = isWorking ? band.species.band.weights.busy : band.species.band.weights.calm
  const pick = Rng.weighted(band.rng, [['walk', w.walk], ['idle', w.idle], ['sit', w.sit], ['sniff', w.sniff]] as const)
  if (pick === 'walk') { go(band, 'walk', 0.1); return }
  band.mode = pick
  band.left = pick === 'idle' ? Rng.range(band.rng, 1500, 4000) : pick === 'sit' ? Rng.range(band.rng, 3000, 6000) : Rng.range(band.rng, 1200, 2200)
}

export function onTurnStart(band: Band, now: number): void {
  band.lastSignalAt = now
  go(band, 'run', 0.25)
}

export function onTool(band: Band, now: number): void {
  band.lastSignalAt = now
  if (band.mode === 'sleep' || band.mode === 'run' || now - band.lastSniffAt < SNIFF_GAP_MS) return
  band.lastSniffAt = now
  band.mode = 'sniff'
  band.left = 1000
}

export function onTurnEnd(band: Band, now: number): void {
  band.lastSignalAt = now
  if (band.mode === 'sleep') return
  band.mode = 'sit'
  band.left = 5000
}

export function onToolStart(band: Band, now: number): void {
  band.lastSignalAt = now
  band.toolsRunning++
}

export function onToolEnd(band: Band, now: number): void {
  band.lastSignalAt = now
  band.toolsRunning = Math.max(0, band.toolsRunning - 1)
}

export function step(band: Band, dtMs: number, now: number, isWorking: boolean): void {
  const dt = Math.min(Names.MAX_CATCHUP_MS, Math.max(0, dtMs))
  band.clock += dt
  if (band.toolsRunning > 0 || isWorking) band.lastSignalAt = Math.max(band.lastSignalAt, now - 1)
  band.x = Math.min(Math.max(band.x, 5), Math.max(5, band.width - 6))
  if (band.mode !== 'sleep' && now - band.lastSignalAt >= Names.SLEEP_AFTER_MS) { band.mode = 'sleep'; band.zAt = band.clock }
  if (band.mode === 'walk' || band.mode === 'run') {
    const v = band.mode === 'run' ? band.species.band.runPxS : band.species.band.walkPxS
    const move = Math.min(Math.abs(band.targetX - band.x), (v * dt) / 1000)
    band.x += band.dir * move
    band.walked += move
    if (Math.abs(band.targetX - band.x) < 0.01) { band.mode = 'idle'; band.left = Rng.range(band.rng, 800, 2000) }
    return
  }
  if (band.mode === 'sleep') return
  band.left -= dt
  if (band.left <= 0) next(band, isWorking)
}

function frameOf(band: Band): BandFrame {
  const f = band.species.band.frames
  switch (band.mode) {
    case 'walk': return Math.floor(band.walked / 3) % 2 === 0 ? f.walkA : f.walkB
    case 'run': return Math.floor(band.walked / 4) % 2 === 0 ? f.runA : f.runB
    case 'sniff': return f.sniff
    case 'sit': return Math.floor(band.clock / 250) % 2 === 0 ? f.sitA : f.sitB
    case 'sleep': return f.sleep
    case 'idle': return Math.floor(band.clock / 600) % 5 === 0 ? f.walkB : f.walkA
  }
}

// 다음 그리기까지 간격
export function renderEveryMs(band: Band): number {
  if (band.mode === 'walk' || band.mode === 'run') return 66
  if (band.mode === 'sleep') return 400
  return 150
}

function buffersFor(band: Band, cols: number): [Buffer, Grid] {
  const b = band.buf
  const g = band.grid
  if (b && g && g.cols === cols) return [b, g]
  const nb = Pixel.bufferOf(cols, Names.BAND_ROWS, 1)
  const ng = Pixel.gridOf(cols, Names.BAND_ROWS)
  band.buf = nb
  band.grid = ng
  return [nb, ng]
}

export function compose(band: Band, cols: number): string {
  band.width = cols
  const [b, g] = buffersFor(band, cols)
  Pixel.clear(b)
  // 바닥 점선
  for (let x = 0; x < cols; x += 2) Pixel.plot(b, x, FLOOR_Y, FLOOR)
  const f = frameOf(band)
  const left = Math.round(band.x) - Math.floor(f.w / 2)
  const top = FLOOR_Y - f.rows.length
  f.rows.forEach((row, y) => {
    for (let i = 0; i < row.length; i++) {
      const role = band.species.band.codes[row[i]!]
      if (role === undefined) continue
      const c = INDEX[role]
      const x = band.dir === 1 ? left + i : left + (f.w - 1 - i)
      Pixel.plot(b, x, top + y, c)
    }
  })
  if (band.mode === 'sleep') {
    // z 가 머리 위로 한 칸씩 올라갔다 사라진다
    const phase = Math.floor((band.clock - band.zAt) / 700) % 3
    const hx = Math.round(band.x) + band.dir * 3
    if (phase < 2) Pixel.plot(b, hx + band.dir * phase, 1 - phase, Z)
  }
  Pixel.fold(b, g, band.rgb)
  return Pixel.encode(g)
}

export * as default from '.'

