import { en } from './en.js'
import { ko } from './ko.js'
import type { Messages } from './types.js'

export type Language = 'en' | 'ko'

export const DEFAULT_LANGUAGE: Language = 'en'

export const MESSAGES: Readonly<Record<Language, Messages>> = { en, ko }

// settings 의 language 처럼 사람이 적은 이름(Korean, 한국어)과 LANG 값(ko_KR.UTF-8)을 앞부분으로 판정한다
export function languageOfText(text: unknown): Language | undefined {
  if (typeof text !== 'string') return undefined
  const value = text.trim().toLowerCase()
  if (/^(ko([_.@-]|$)|korean|한국)/.test(value)) return 'ko'
  if (/^(en([_.@-]|$)|english)/.test(value)) return 'en'
  return undefined
}

// userConfig 의 language 가 en·ko 면 그 값이다. auto 거나 비어 있으면 candidates(settings 의 language, LC_ALL, LANG 순)에서
// 처음 판정되는 값, 아무것도 판정되지 않으면 기본값이다
export function languageOf(option: unknown, candidates: readonly unknown[] = []): Language {
  if (option === 'en' || option === 'ko') return option
  for (const candidate of candidates) {
    const language = languageOfText(candidate)
    if (language) return language
  }
  return DEFAULT_LANGUAGE
}

export function messagesOf(language: Language): Messages {
  return MESSAGES[language]
}

files.hooks/pet/state.ts:
// 강아지 상태(순수 모듈). 이동(motion.ts), 행동 고르기(brain.ts), 그릴 모습(pose.ts)이 이 값을 나눠 쓴다.

import Rng from '../rng'
import type { Reach, Tile } from '../path'
import World, { type World as WorldState } from '../world'
import Species, { type SpeciesDef } from '../species'
import * as Ball from './ball.js'
import type { Ball as BallState } from './ball.js'
import type { Emote, Particle } from './fx.js'

// 세계 축 방향. 화면에서 SE 는 오른쪽 아래, SW 는 왼쪽 아래, NW 는 왼쪽 위, NE 는 오른쪽 위
export type Dir = 'SE' | 'SW' | 'NW' | 'NE'

export const DIR_VEC: Record<Dir, readonly [number, number]> = { SE: [1, 0], SW: [0, 1], NW: [-1, 0], NE: [0, -1] }
export const DIRS: readonly Dir[] = ['SE', 'SW', 'NW', 'NE']

export function isRight(d: Dir): boolean {
  return d === 'SE' || d === 'NE'
}

export function isBack(d: Dir): boolean {
  return d === 'NE' || d === 'NW'
}

export function dirOf(dx: number, dy: number): Dir {
  if (Math.abs(dx) >= Math.abs(dy)) return dx >= 0 ? 'SE' : 'NW'
  return dy >= 0 ? 'SW' : 'NE'
}

export type Gait = 'walk' | 'trot' | 'run' | 'sniff' | 'creep'

// 멈춰서 하는 자세
export type PoseName =
  | 'stand' | 'look' | 'pant' | 'sniff' | 'dig' | 'bow' | 'shake' | 'scratch' | 'yawn' | 'stretch'
  | 'sit' | 'frontSit' | 'lie' | 'lieRest' | 'sleep' | 'wake'
  | 'roll' | 'drink' | 'chew' | 'tilt' | 'alert' | 'beg' | 'droop'
  // 앉아 앞발을 핥는다(고양이가 도구 호출 때 땅 파기 대신)
  | 'groom'

// 이 종이 실제로 하는 자세: 종이 다른 자세로 바꾸는 자세면 바꾼 것
export function poseFor(species: SpeciesDef, name: PoseName): PoseName {
  return species.behavior.poseMap[name] ?? name
}

// go: to 가 있으면 그 칸, pick 이 있으면 단계를 시작할 때 지금 자리에서 걸음 수 [lo, hi] 인 칸을 고른다(front 면 화면 앞쪽 칸, toward 면 그 방향으로 가장 먼 칸).
// must 면 길이 없을 때 행동 전체를 그만둔다(목적지가 핵심인 행동). 아니면 그 단계만 건너뛴다.
// pose 의 grow: 도구 호출이 이어지면 이 자세를 늘린다(새로 시작하지 않는다). splash: 서 있는 동안 발 둘레에 물보라를 튀긴다.
// hop: 제자리에서 솟았다 내려온다
export type Step =
  | { k: 'go'; to?: Tile; pick?: { lo: number; hi: number; front?: boolean; toward?: Dir }; gait: Gait; must?: boolean }
  | { k: 'pose'; pose: PoseName; ms: number; face?: Dir; emote?: Emote['kind']; grow?: boolean; splash?: boolean }
  | { k: 'hop'; peakPx: number; ms: number }
  | { k: 'spin'; quarters: number; msPer: number }
  | { k: 'pounce' }
  | { k: 'kick' }
  | { k: 'chase' }
  // 공을 입에 문다(가까이 있을 때), 내려놓는다
  | { k: 'grab' }
  | { k: 'drop' }
  // 선 칸의 나뭇가지를 문다(없으면 행동을 끝낸다), 문 나뭇가지를 내려놓는다
  | { k: 'take' }
  | { k: 'put' }
  // 선 칸에 구덩이 흔적을 남긴다
  | { k: 'pit' }

export type ActName =
  | 'idle' | 'walk' | 'run' | 'sniff' | 'play' | 'sit' | 'lie'
  | 'explore' | 'roam' | 'patrol' | 'perch' | 'rollOver' | 'watch' | 'nap' | 'drink' | 'splash' | 'chew' | 'digSpot' | 'swim'
  | 'greet' | 'dig' | 'settle' | 'bedtime'
  | 'wakeUp' | 'attend' | 'ponder' | 'seeOff' | 'shakeOff' | 'nose' | 'alert' | 'bark' | 'wait' | 'beg' | 'sulk' | 'startle' | 'puzzled'

// 놀이 변형
export type PlayName = 'ball' | 'fetch' | 'spin' | 'pounce' | 'stalk' | 'chaseTail' | 'zoomies'

// 욕구 0~1. 쉬고 싶은 정도는 1 - energy 로 따로 계산한다
export type Needs = { curiosity: number; play: number; social: number; thirst: number }

// started: 시작 처리를 마친 단계 번호. i 와 다르면 그 단계를 막 시작한 것이다. aborted: 목적지를 못 찾아 그만뒀다.
// ordered: 사람이 명령(/pets do)으로 시킨 행동. 사람 직접 부류로 반응하고 평소 행동 기록에 넣지 않는다
export type Activity = { name: ActName; steps: Step[]; i: number; t: number; started: number; aborted?: boolean; ordered?: boolean }

// 행동 부류. 신호가 지금 행동을 끊을지는 부류로 정한다.
// N 평소, S 잠, A 가벼운 반응, T 도구 반응, P 권한 대기, E 턴 결과, G 사람 직접
export type ActClass = 'N' | 'S' | 'A' | 'T' | 'P' | 'E' | 'G'

// 행동을 고를 때 한 번 돌리는 BFS. 그 선택에서 만드는 모든 목적지가 이것을 나눠 쓴다
// memo: 여러 행동이 같은 선택 안에서 다시 쓰는 질의 결과(높은 칸, 블록 둘레 등)
export type Survey = { from: Tile; reach: Reach; memo: Map<string, unknown> }

// 최근 평소 행동을 이만큼 기억한다([0] 이 직전)
export const HISTORY_SIZE = 6

// 신호 종류마다 따로 두는 토큰 통. 통이 비면 그 신호는 행동을 바꾸지 않는다
export type BucketName = 'toolMain' | 'toolSub' | 'attend' | 'error'
export type Bucket = { tokens: number; at: number }
// 통마다 담을 수 있는 토큰 수와 토큰 하나가 다시 차는 시간(ms). 메인 도구 호출, 서브에이전트 도구 호출, 타이핑, 도구 실패
export const BUCKETS: Readonly<Record<BucketName, { cap: number; everyMs: number }>> = {
  toolMain: { cap: 2, everyMs: 1500 },
  toolSub: { cap: 1, everyMs: 4000 },
  attend: { cap: 1, everyMs: 4000 },
  error: { cap: 1, everyMs: 3000 },
}

export type Hop = { fx: number; fy: number; tx: number; ty: number; z0: number; z1: number; t: number; dur: number; peak: number; isPath: boolean }

export type Pet = {
  // 종 정의. 걸음·그림·기운 수치를 여기서 읽는다
  species: SpeciesDef
  // 위치(타일 좌표, 칸 가운데가 정수)와 발 높이(px)
  x: number
  y: number
  z: number
  dir: Dir
  speed: number
  gait: Gait
  // 남은 경유 칸. 첫 칸이 지금 가는 곳
  path: Tile[]
  hop?: Hop
  // 뛰기 전 웅크림, 착지 뒤 눌림(ms)
  crouchMs: number
  landMs: number
  // 걸음 위상: 걸은 거리 ÷ 보폭. 발이 바닥에서 미끄러지지 않게 시간이 아니라 거리로 돈다
  stride: number
  // 좌우가 뒤집힐 때 정면 모습을 잠깐 보인다
  turnMs: number
  // 헤엄치는 종이 물 칸(얕은 물 포함)에 있다(이동 스텝마다 정한다). 헤엄 걸음으로 움직이고 헤엄 몸으로 그린다
  swimming: boolean
  act: Activity
  // 이벤트가 만든 행동. 지금 이벤트 행동이 끝나면 차례로 한다
  queue: Activity[]
  // 끝났거나 끊긴 평소 행동, [0] 이 직전. 그 행동이 끝난 시뮬레이션 시각
  history: ActName[]
  lastEndAt: Partial<Record<ActName, number>>
  // 시뮬레이션 시각(ms). 고정 스텝마다 늘어난다. 행동의 대기 시간·기록은 실제 시각이 아니라 이것으로 잰다
  simMs: number
  // 목적지를 못 찾아 그만둔 행동은 이 시각(시뮬레이션 ms)까지 다시 고르지 않는다. aborts 는 그만둔 횟수
  blockedUntil: Partial<Record<ActName, number>>
  aborts: number
  needs: Needs
  // 마지막으로 행동을 고를 때 16 걸음 안에 물가가 있었는지. 새로 만든 동물은 첫 선택 전까지 없다고 본다(목마름이 0 으로 묶인다)
  waterNear: boolean
  // 최근 놀이 변형, [0] 이 직전
  playHistory: PlayName[]
  // 칸 키마다 마지막으로 서 있던 시뮬레이션 시각. 새 칸을 고르는 데 쓴다. 가장 오래된 것부터 버린다
  visits: Map<number, number>
  tileKey: number
  // 사람이 직접 보낸 신호(프롬프트, 타이핑)의 실제 시각
  lastHumanAt: number
  // 실제 시각(ms). 메인 턴이 시작한 때(턴이 없으면 undefined), 메인 도구가 0 개에서 1 개가 된 때,
  // 권한 대기가 시작한 때, 도구 실패 반응이 마지막으로 나온 때, 메인 루프 생각 조각이 글·도구 조각 없이 이어지기 시작한 때
  turnStartedAt?: number
  toolSince?: number
  permissionSince?: number
  lastFailAt: number
  thinkSince?: number
  buckets: Record<BucketName, Bucket>
  // 행동·자세를 그대로 두고 얼굴만 잠깐 돌린다. 돌리기 전 방향으로 되돌린다
  glance?: { dir: Dir; back: Dir; ms: number }
  // 자는 중 신호가 오면 다음 z 하나를 건너뛴다
  skipZ: boolean
  // 공을 입에 물고 있다
  carrying: boolean
  // 나뭇가지를 물고 있다. from 은 집어 든 칸(내려놓을 곳이 없으면 그리로 되돌린다)
  holding?: { from: Tile }
  pose: PoseName
  // 0~1. 뛰고 놀면 줄고 쉬고 자면 찬다. 낮으면 앉고 눕는 쪽을 고른다
  energy: number
  // 0~1. 세션 신호가 오면 오르고 시간이 지나면 식는다. 높으면 뛰고 논다
  excite: number
  isAsleep: boolean
  // 실제 시각(ms). 잠 자세에 들어간 때. 이만큼 자고 기운이 차면 스스로 깬다
  sleepSince?: number
  // 신호가 없어도 잠들지 않는다(/pets idle on)
  keepAwake: boolean
  // 꼬리·숨·깜빡임 시계(ms)
  tail: number
  breath: number
  blinkIn: number
  blinkMs: number
  emote?: Emote
  particles: Particle[]
  fxClock: number
  ball: BallState
  // 행동 난수. 깜빡임·파티클은 fxRng 를 써서, 그리기 쪽을 바꿔도 행동 순서가 달라지지 않는다
  rng: Rng.Rng
  fxRng: Rng.Rng
  // 실제 시각(ms). 신호가 마지막으로 온 때, 흐름(스트리밍)이 이어지는 동안
  lastSignalAt: number
  busyUntil: number
  // 돌고 있는 도구 수(서브에이전트 것 포함, 잠들지 않게 한다)와 그중 메인 루프 것
  toolsRunning: number
  mainTools: number
}

function idleActivity(): Activity {
  return { name: 'idle', steps: [{ k: 'pose', pose: 'stand', ms: 1500 }], i: 0, t: 0, started: -1 }
}

export function create(world: WorldState, seed: number, now: number, species: SpeciesDef = Species.DOG): Pet {
  const rng = Rng.create(seed ^ 0x9e3779b9)
  const { x, y } = world.spawn
  // 공은 시작 자리에서 몇 칸 떨어진 걷는 칸에 둔다. 경사 칸은 뺀다(두자마자 굴러간다)
  let bx = x
  let by = y
  for (let i = 0; i < 60; i++) {
    const cx = x + Rng.int(rng, -5, 5)
    const cy = y + Rng.int(rng, -5, 5)
    if (World.isWalkable(world, cx, cy, species.abilities) && (cx !== x || cy !== y) && !World.slopeDirAt(world, cx, cy)) { bx = cx; by = cy; break }
  }
  return {
    species, x, y, z: World.surfaceZ(world, x, y),
    dir: 'SE', speed: 0, gait: 'walk', path: [], crouchMs: 0, landMs: 0, stride: 0, turnMs: 0, swimming: false,
    act: idleActivity(), queue: [], history: [], lastEndAt: {}, simMs: 0, blockedUntil: {}, aborts: 0,
    needs: { curiosity: 0.4, play: 0.3, social: 0.3, thirst: 0 }, waterNear: false, playHistory: [], visits: new Map(), tileKey: keyOf(x, y), lastHumanAt: now, carrying: false,
    pose: 'stand',
    energy: species.behavior.initial.energy, excite: species.behavior.initial.excite, isAsleep: false, keepAwake: false,
    tail: 0, breath: 0, blinkIn: 2500, blinkMs: 0,
    particles: [], fxClock: 0,
    ball: Ball.create(bx, by, world),
    rng, fxRng: Rng.create(seed ^ 0x51f15e), lastSignalAt: now, busyUntil: 0, toolsRunning: 0, mainTools: 0,
    lastFailAt: -Infinity, skipZ: false,
    buckets: {
      toolMain: { tokens: BUCKETS.toolMain.cap, at: now }, toolSub: { tokens: BUCKETS.toolSub.cap, at: now },
      attend: { tokens: BUCKETS.attend.cap, at: now }, error: { tokens: BUCKETS.error.cap, at: now },
    },
  }
}

// 칸 좌표를 한 수로. |좌표| < 32768 에서 겹치지 않는다
export function keyOf(x: number, y: number): number {
  return (x & 0xffff) | (y << 16)
}

export function tileOf(p: Pet): Tile {
  return { x: Math.round(p.x), y: Math.round(p.y) }
}

export function isMoving(p: Pet): boolean {
  return p.speed > 0.05 || p.hop !== undefined || p.crouchMs > 0
}

files.hooks/pet/brain.ts:
// 행동 고르기와 세션 신호 반응(순수 모듈).
//
// 행동(Activity)은 단계(Step) 목록이다: 어디로 가기, 자세 몇 ms, 제자리 돌기, 폴짝, 공 차기·쫓기·물기·놓기, 나뭇가지 물기·놓기, 구덩이 흔적 남기기.
// 행동마다 정의(ActDef)가 하나씩 있다: 부류, 기본 가중치, 욕구 계수, 대기 시간, 가중치 배율, 할 수 있는지, 단계 만들기.
//
// 평소 행동은 점수에 비례해 난수로 뽑는다(가장 높은 점수를 고르지 않아 같은 욕구 상태에서도 행동이 갈린다).
//   점수 = 기본 가중치 × 종 배율 × 할 수 있는지 × 대기 시간이 지났는지 × 반복 벌점 × 기운·들뜸·바쁨 배율 × 욕구 항
//   반복 벌점 = max(0.1, 1 - 최근 6 개 중 같은 행동 자리마다 0.65, 0.30, 0.15, 0.08, 0.04, 0.02 를 더한 값)
//   욕구 항 = min(3, 0.35 + Σ 욕구 계수 × 욕구). 욕구는 호기심·놀고 싶음·사람 곁·목마름과 쉬고 싶음(1 - 기운)
// 기운이 아주 낮으면 뽑기 전에 낮잠을 고르고, 모든 점수가 0 이면 가만히 선다.
// 신호 없이 SLEEP_AFTER_MS 가 지나면 잠들고(잠들지 않기가 켜져 있으면 안 잔다), 잠든 지 SLEEP_MS 가 지나고 기운이 차면 스스로 깬다.
// 사람이 명령으로 시킨 행동(order)은 사람 직접 부류로 반응하고 평소 행동 기록에 넣지 않는다.
// 세션 신호가 지금 행동에 하는 일은 신호 종류 × 지금 행동 부류 표(RULES)가 정한다: 끊고 시작, 대기열 앞·뒤, 늘리기, 되돌려 놓고 끊기, 버리기, 얼굴만 돌리기.
// 도구 호출·서브에이전트 도구 호출·타이핑·도구 실패는 토큰 통을 거쳐, 몰려 와도 행동이 몇 번만 바뀐다.
// 한 번 고를 때 BFS 는 한 번만 돌리고(Survey), 그 선택의 판정과 목적지가 모두 그 결과를 쓴다.

