// 이 기운 아래면 뽑기 전에 낮잠
const NAP_NOW = 0.12
// 이보다 오래 안 간 칸이 "새 칸"
const FRESH_MS = 120_000
const VISITS_MAX = 512
// 사람 신호가 이만큼 없으면 사람 곁에 가고 싶어진다
